function neighborhood(p: Project, id: string) {
  const byId = new Map(p.descriptions.map(d => [d.id, d]));
  const parentOf = (id: string) => parentDescription(p, id, byId)?.id ?? null;
  const children = (id: string | null) => p.descriptions.filter(d => parentOf(d.id) === id);
  const parent = parentOf(id), rows = children(parent);
  return { byId, children, parent, rows };
}
function moveDescription(action: 'up' | 'down' | 'back' | 'enter') {
  const p = current.project, id = current.selection.description;
  if (!p || !id) return;
  const { parent, rows, children } = neighborhood(p, id);
  const index = rows.findIndex(d => d.id === id);
  const destination = action === 'back' ? parent : action === 'enter' ? children(id)[0]?.id :
    index < 0 ? undefined : rows[index + (action === 'up' ? -1 : 1)]?.id;
  if (destination && destination !== id) { optionsOpen = false; void open({ description: destination }); }
}
function descriptionMenu(p: Project) {
  const menuCursor = current.selection.description ?? '';
  const { byId, children, parent, rows } = neighborhood(p, menuCursor);
  const index = rows.findIndex(d => d.id === menuCursor);
  const dock = el('section', undefined, 'description-menu'); dock.setAttribute('aria-label', 'Description navigation');
  if (!menuOpen) return dock;
  const body = el('div', undefined, 'menu-body'); body.id = 'menu-body';
  const list = el('div', undefined, 'menu-list'); list.id = 'description-options'; list.tabIndex = 0;
  list.setAttribute('role', 'listbox'); list.setAttribute('aria-label', 'Descriptions at this level');
  if (index >= 0) list.setAttribute('aria-activedescendant', `description-option-${index}`);
  rows.forEach((d, i) => {
    const row = el('div', undefined, 'menu-option' + (d.id === menuCursor ? ' cursor' : ''));
    row.id = `description-option-${i}`; row.setAttribute('role', 'option'); row.setAttribute('aria-selected', String(d.id === menuCursor));
    row.append(el('span', d.title));
    const count = children(d.id).length;
    if (count) row.append(el('span', '›', 'menu-count'));
    row.onclick = () => { focusMenu = true; void open({ description: d.id }); };
    list.append(row);
  });
  list.onkeydown = e => {
    if (e.altKey || e.ctrlKey || e.metaKey || e.shiftKey) return;
    if (e.key === 'Enter' && menuCursor) { e.preventDefault(); void open({ description: menuCursor }); }
    else if (e.key === 'Escape') { e.preventDefault(); menuOpen = false; render(); document.querySelector<HTMLButtonElement>('#menu-toggle')?.focus(); }
    else if (e.key === 'Home' || e.key === 'End') {
      e.preventDefault(); const target = rows[e.key === 'Home' ? 0 : rows.length - 1];
      if (target) void open({ description: target.id });
    }
  };
  const column = (name: string) => {
    const section = el('section', undefined, 'menu-column'); section.setAttribute('aria-label', name);
    return section;
  };
  const parentColumn = column('Parent description');
  if (parent) parentColumn.append(button(byId.get(parent)!.title, () => void open({ description: parent }), 'menu-neighbor'));

  const currentColumn = column('Current level'); currentColumn.append(list);
  const childColumn = column('Child descriptions');
  const childList = el('div', undefined, 'menu-neighbors');
  for (const child of children(menuCursor)) childList.append(button(child.title, () => void open({ description: child.id }), 'menu-neighbor'));

  childColumn.append(childList);
  body.append(parentColumn, currentColumn, childColumn); dock.append(body); return dock;
}

async function navigate(request: UIRequest): Promise<Selection> {
  if (!request || !['current', 'open'].includes(request.action)) throw new Error('Use current or open.');
  if (request.action === 'current') return selection;
  if (typeof request.description !== 'string' || (request.revision !== undefined && typeof request.revision !== 'string') ||
      (request.passage !== undefined && !isPassage(request.passage))) throw new Error('Invalid description selection.');
  const requested = request.revision ?? selection.revision;
  const pinned = requested === 'working' ? requested : git(root, ['rev-parse', '--verify', '--end-of-options', `${requested}^{commit}`]).trim();
  let { project } = await viewData(root, pinned);
  if (!project.descriptions.some(d => d.id === request.description)) ({ project } = await viewData(root, pinned, true));
  getDescription(project, request.description);
  if (request.passage) targetContent(project, { description: request.description, passage: request.passage });
  selection = { project: root, revision: pinned, description: request.description, ...(request.passage ? { passage: request.passage } : {}) };
  window.webContents.send('selection', selection);
  return selection;
}
async function attach(path: string) {
  const next = repository(path);
  const { project } = await viewData(next, 'working', true);
  if (!project.config && !project.descriptions.length) throw new Error('This folder has no readable Stratic project.');
  const nextUI = next === root && stopUI ? stopUI : await serveUI(next, navigate);
  if (nextUI !== stopUI) stopUI?.();
  root = next; stopUI = nextUI;
  selection = { project: root, revision: 'working', description: project.descriptions.find(d => d.metadata?.parent === null)?.id ?? project.descriptions[0]?.id };
  projects = [root, ...projects.filter(path => path !== root)].slice(0, 12);
  try { writeFileSync(join(app.getPath('userData'), 'projects.json'), JSON.stringify(projects)); }
  catch (error) { console.error('Could not save recent projects:', error); }
}
async function view() {
  if (!root) return { tree: '', selection, projects, project: null, checks: [], ready: null, history: [], dirty: false, comparison: null };
  const at = selection;
  const data = await viewData(root, at.revision);
  if (selection !== at) return view();
  return { ...data, selection: at, projects };
}

import { Worker } from 'node:worker_threads';
import { join } from 'node:path';
import type { Project, CheckResult, Ready } from '../model.ts';
import type { Comparison } from './comparison.ts';
export interface ViewData {
  tree: string; project: Project; checks: (CheckResult & { current: boolean })[]; ready: Ready | null;
  history: { id: string; title: string }[]; dirty: boolean; comparison: Comparison | null;
}
let worker: Worker | undefined, nextId = 0;
const pending = new Map<number, { resolve: (v: ViewData) => void; reject: (e: Error) => void }>();
const cache = new Map<string, { value?: ViewData; loading?: Promise<ViewData>; updated: number; error?: Error }>();
function request(root: string, revision: string): Promise<ViewData> {
  if (!worker) {
    worker = new Worker(join(__dirname, 'view-worker.cjs'));
    worker.on('message', ({ id, value, error }) => {
      const promise = pending.get(id); pending.delete(id);
      if (error) promise?.reject(new Error(error)); else promise?.resolve(value);
    });
    worker.on('error', error => { for (const promise of pending.values()) promise.reject(error); pending.clear(); worker = undefined; cache.clear(); });
  }
  return new Promise((resolve, reject) => { const id = ++nextId; pending.set(id, { resolve, reject }); worker!.postMessage({ id, root, revision }); });
}
export async function viewData(root: string, revision: string, fresh = false): Promise<ViewData> {
  const key = JSON.stringify([root, revision]);
  let entry = cache.get(key);
  if (!entry) {
    if (cache.size >= 4) { const oldest = [...cache].find(([, value]) => !value.loading); if (oldest) cache.delete(oldest[0]); }
    entry = { updated: 0 }; cache.set(key, entry);
  }
  if (!entry.loading && (fresh || !entry.value || Date.now() - entry.updated > 2000)) {
    const saved = entry;
    saved.loading = request(root, revision).then(value => { saved.value = value; saved.error = undefined; saved.updated = Date.now(); return value; }).catch(error => { saved.error = error; throw error; }).finally(() => { saved.loading = undefined; });
    // A background failure is surfaced by a fresh request; it must not crash the desktop.
    saved.loading.catch(() => {});
  }
  if (fresh || !entry.value) return entry.loading!;
  if (entry.error) throw new Error('Project refresh failed: ' + entry.error.message);
  return entry.value;
}
export function stopViewWorker() { void worker?.terminate(); worker = undefined; }

import { parentPort } from 'node:worker_threads';
import { workingSnapshot, git } from '../git.ts';
import { loadProject } from '../project.ts';
import { ready, results, reviewHistory } from '../review.ts';
import type { CheckResult } from '../model.ts';
import { comparison } from './comparison.ts';
import { matchesReviewContent } from '../review-records.ts';

function view(root: string, revision: string) {
  const project = loadProject(root, revision);
  const pending = ready(root);
  const tree = revision === 'working' ? workingSnapshot(root) : project.revision;
  const history = reviewHistory(root, project.revision);
  const equivalents = new Set([tree]);
  // Compare actual content, excluding only each review's own newly-added record.
  for (const { path, review } of history) {
    if (matchesReviewContent(root, tree, path, review)) equivalents.add(review.contentTree);
  }
  const checks = new Map<string, CheckResult>();
  for (const result of [...(revision === 'working' ? results(root) : []), ...history.flatMap(h => Array.isArray(h.review.results) ? h.review.results : [])]) {
    if (result && typeof result.id === 'string' && Array.isArray(result.tests)) checks.set(result.id, result);
  }
  const branches = git(root, ['log', '-12', '--format=%H%x09%s']).trim().split('\n').map(line => { const [id, ...title] = line.split('\t'); return { id, title: title.join('\t') }; });
  return { tree, project, comparison: comparison(root, project, pending, history, tree), ready: pending, history: branches,
    dirty: !!git(root, ['status', '--porcelain']).trim(),
    checks: [...checks.values()].sort((a, b) => b.recordedAt.localeCompare(a.recordedAt)).map(r => ({ ...r, current: equivalents.has(r.tree) })) };
}
parentPort!.on('message', ({ id, root, revision }) => {
  try { parentPort!.postMessage({ id, value: view(root, revision) }); }
  catch (e) { parentPort!.postMessage({ id, error: (e as Error).message }); }
});

async function refresh(force = false) {
  const ticket = ++sequence;
  try {
    const v = await window.stratic.view(); if (ticket !== sequence) return;
    const next = JSON.stringify(v);
    if (next === signature && !force) return;
    const key = JSON.stringify(v.selection);
    if (current && v.project?.root !== current.project?.root) expandedTests.clear();
    if (key !== loadedKey) { clearDetail(); tab = 'description'; loadedKey = key; }
    if (source) {
      const openedSource = source;
      try {
        const body = await window.stratic.source(openedSource.path);
        if (ticket !== sequence || source !== openedSource) return;
        openedSource.body = body;
        try { openedSource.range = resolvePassage(body, openedSource.passage); openedSource.problem = undefined; }
        catch (e) { openedSource.range = undefined; openedSource.problem = (e as Error).message + ' Select the updated description passage to follow its current link.'; }
      } catch (e) {
        if (ticket !== sequence || source !== openedSource) return;
        openedSource.body = ''; openedSource.range = undefined;
        openedSource.problem = 'Source unavailable: ' + (e as Error).message;
      }
    }
    current = v; signature = next; render();
    if (v.selection.passage) document.querySelector('.active-description .selected')?.scrollIntoView({ block: 'center' });
  } catch (e) { error(e); }
}
